export const Z_MOTOR_SOURCE=withZMotorSourceLocales({"url": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994", "translations": {"en": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994"}, "applicability": ["core-one", "core-one-family", "core-one-plus", "core-one-indx"], "Gen2ExplicitlySupported": false, "localeFallbacks": {"cs": "en", "de": "en"}, "steps": [{"id": 576213, "number": 1, "webNumber": 2, "title": ["Zモーターの種類と交換範囲", "Introduction", "Introduction", "Introduction"], "body": ["CORE OneのZモーターを交換します。プリンターを正面から見た前左・前右・後方から、交換する位置を選びます。前側2個の交換と、全3個の手順を確認する選択もあります。前側2個は短いケーブルの「Z-Axis LEFT」、後方1個は「Z-Axis RIGHT」です。選んだ位置に必要なモーターを用意してください。", "This guide will take you through the Z motors replacement on the Prusa CORE One.\nSpare parts are available in our eshop prusa3d.com.\nThere are two types of the Z-motors on the CORE One printer. These are the same types as used on the MK4/S printers.\nThe two of the front motors have a short cable and are labeled as LEFT.\nThe motor in the back is labeled as RIGHT.", "This guide will take you through the Z motors replacement on the Prusa CORE One.\nSpare parts are available in our eshop prusa3d.com.\nThere are two types of the Z-motors on the CORE One printer. These are the same types as used on the MK4/S printers.\nThe two of the front motors have a short cable and are labeled as LEFT.\nThe motor in the back is labeled as RIGHT.", "This guide will take you through the Z motors replacement on the Prusa CORE One.\nSpare parts are available in our eshop prusa3d.com.\nThere are two types of the Z-motors on the CORE One printer. These are the same types as used on the MK4/S printers.\nThe two of the front motors have a short cable and are labeled as LEFT.\nThe motor in the back is labeled as RIGHT."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#576213", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2025/09/b49c64e23b1e1a0a_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2025/09/b49c64e23b1e1a0a_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2025/11/fd9948273eb2cf8ccb5f1ecc4ca2d22a_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2025/11/fd9948273eb2cf8ccb5f1ecc4ca2d22a_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [576222, 576230, 1038083, 1038084, 1038085]}, {"id": 1038107, "number": 2, "webNumber": 3, "title": ["工具を用意する", "Tools Required", "Tools Required", "Tools Required"], "body": ["2.5 mm六角レンチ、T10トルクス、先細ペンチを用意します。結束バンドを切るためのニッパーは任意です。取り外したねじ・ピン・ゴム足・マウントを分けて置ける場所も確保します。", "Please prepare tools for this guide:\n2.5mm Allen key\nT10 Torx key / screwdriver\nNeedle-nose pliers\nFlush cutters are recommended as an optional tool.", "Please prepare tools for this guide:\n2.5mm Allen key\nT10 Torx key / screwdriver\nNeedle-nose pliers\nFlush cutters are recommended as an optional tool.", "Please prepare tools for this guide:\n2.5mm Allen key\nT10 Torx key / screwdriver\nNeedle-nose pliers\nFlush cutters are recommended as an optional tool."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1038107", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/7674d9e095959b48a4250c42d32d49c5_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/7674d9e095959b48a4250c42d32d49c5_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2025/11/4f63c25a60a004060175c752408e55f4_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2025/11/4f63c25a60a004060175c752408e55f4_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1038108, 1038109, 1038110, 1038111, 1038112]}, {"id": 1038157, "number": 3, "webNumber": 4, "title": ["冷却し、Auto Homeを実行する", "Printer Preparation 1", "Printer Preparation 1", "Printer Preparation 1"], "body": ["プリンターが室温まで冷えていることを確認します。実機のControl → Auto Homeを実行し、ヒートベッドが一番上へ移動して停止するまで待ちます。", "Before you begin, make sure the printer has cooled down to ambient temperature.\nOn the printer, visit the menu Control and trigger the Auto Home.\nThe heatbed should move all the way up.", "Before you begin, make sure the printer has cooled down to ambient temperature.\nOn the printer, visit the menu Control and trigger the Auto Home.\nThe heatbed should move all the way up.", "Before you begin, make sure the printer has cooled down to ambient temperature.\nOn the printer, visit the menu Control and trigger the Auto Home.\nThe heatbed should move all the way up."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1038157", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2025/09/b0bf8e7f07d875f8bfa12da9e6fc5c9d_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2025/09/b0bf8e7f07d875f8bfa12da9e6fc5c9d_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/bd26cd28ed103fc26090b62cde4be3aa_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/bd26cd28ed103fc26090b62cde4be3aa_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1038158, 1038159, 1038161]}, {"id": 1038197, "number": 4, "webNumber": 5, "title": ["電源を切り、コードを抜く", "Printer Preparation 2", "Printer Preparation 2", "Printer Preparation 2"], "body": ["背面スイッチで電源を切り、電源コードをプリンターから抜きます。以降の配線作業は電源を切った状態で行います。", "Turn the printer off using the switch on the back.\nDisconnect the printer from power.", "Turn the printer off using the switch on the back.\nDisconnect the printer from power.", "Turn the printer off using the switch on the back.\nDisconnect the printer from power."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1038197", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2025/10/e80dc18a2e607038_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2025/10/e80dc18a2e607038_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1038198, 1038199]}, {"id": 1038221, "number": 5, "webNumber": 6, "title": ["xLCDのフックを外す", "xLCD Removal 1", "xLCD Removal 1", "xLCD Removal 1"], "body": ["xLCDの下側を持ち上げて外へ傾けます。右側を動かして側板のフックを外し、外へ移動させます。左側のフックも左の側板から確実に外してください。配線を引っ張りません。", "We need to remove the xLCD. \nStart by lifting the bottom part of the LCD up, in order to tilt the assembly outward.\nThen, move the right side of the assembly until the hook on the right disengages from the side panel.\nMove the assembly outward.\nMake sure to disengage the hook on the left side from the left side panel.", "We need to remove the xLCD. \nStart by lifting the bottom part of the LCD up, in order to tilt the assembly outward.\nThen, move the right side of the assembly until the hook on the right disengages from the side panel.\nMove the assembly outward.\nMake sure to disengage the hook on the left side from the left side panel.", "We need to remove the xLCD. \nStart by lifting the bottom part of the LCD up, in order to tilt the assembly outward.\nThen, move the right side of the assembly until the hook on the right disengages from the side panel.\nMove the assembly outward.\nMake sure to disengage the hook on the left side from the left side panel."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1038221", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2025/11/fa5d0c542ce2f14664022f96cddcd1d3_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2025/11/fa5d0c542ce2f14664022f96cddcd1d3_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2025/02/9ee5d71c408e420a9477e7e1ca8cf900_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2025/02/9ee5d71c408e420a9477e7e1ca8cf900_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1038222, 1038223, 1038224, 1038225]}, {"id": 1038263, "number": 6, "webNumber": 7, "title": ["xLCDの2本の接続を外す", "xLCD Removal 2", "xLCD Removal 2", "xLCD Removal 2"], "body": ["xLCD背面のメインケーブルをコネクター本体を持って抜き、接地線のFaston端子も抜きます。xLCD一式を取り出し、静電気に配慮した場所へ保管します。取り外した2本のケーブルは本体側に残します。", "Disconnect the main cable from the connector on the back of the xLCD.\nDisconnect the grounding faston.\nMove the xLCD assembly away and store it in an ESD-safe environment.", "Disconnect the main cable from the connector on the back of the xLCD.\nDisconnect the grounding faston.\nMove the xLCD assembly away and store it in an ESD-safe environment.", "Disconnect the main cable from the connector on the back of the xLCD.\nDisconnect the grounding faston.\nMove the xLCD assembly away and store it in an ESD-safe environment."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1038263", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2025/03/a68fe7d6e4cc359e5a9853defe71bd3a_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2025/03/a68fe7d6e4cc359e5a9853defe71bd3a_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/3baf8e51a981dbbff4f88427934a233d_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/3baf8e51a981dbbff4f88427934a233d_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1038264, 1038265, 1038266]}, {"id": 1038297, "number": 7, "webNumber": 8, "title": ["左側の板金パネルを外す", "L Side Panel Removal", "L Side Panel Removal", "L Side Panel Removal"], "body": ["左側の板金パネルを固定するナイロンリベット11個を、それぞれロックピンを解除して抜きます。パネルを取り外して保管します。周囲の構造用ねじを代わりに外しません。", "Remove the 11 Nylon rivets holding the side panel on the left side.\nRemove the side panel.", "Remove the 11 Nylon rivets holding the side panel on the left side.\nRemove the side panel.", "Remove the 11 Nylon rivets holding the side panel on the left side.\nRemove the side panel."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1038297", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/7eddd17d25cb54f8a7562417a4a83f7f_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/7eddd17d25cb54f8a7562417a4a83f7f_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1038298, 1038299]}, {"id": 1038421, "number": 8, "webNumber": 9, "title": ["背面を下にして寝かせる", "Printer Positioning", "Printer Positioning", "Printer Positioning"], "body": ["プリンターを背面側へゆっくり倒し、前面が上を向くように置きます。フレームを安定して支え、配線や外したLCDを下敷きにしません。ベッドは上端位置のまま保持し、一度に外すZモーターは1個です。", "Lay the printer onto its back in order to access its bottom part.\nThe front of the printer should face upward.", "Lay the printer onto its back in order to access its bottom part.\nThe front of the printer should face upward.", "Lay the printer onto its back in order to access its bottom part.\nThe front of the printer should face upward."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1038421", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/5c5669583c7d6ceb241f3c98f94eef19_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/5c5669583c7d6ceb241f3c98f94eef19_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1038422, 1038423]}, {"id": 1038326, "number": 9, "webNumber": 10, "title": ["前側交換に必要なゴム足を保管する", "Antivib Feet Removal", "Antivib Feet Removal", "Antivib Feet Removal"], "body": ["前側Zモーターを交換する場合は、背面側の防振ゴム足2個を丁寧にはがして保管します。粘着テープで固定されており、後で再使用します。初期型の異なる足では、フレームを分離できる範囲だけ底部をはがします。後側モーターだけの交換では前側用のフレーム分解は不要です。", "In case you will be replacing one of the front Z motors, the bottom frame will need to be partially disassembled and two of the rubber feet removed.\nCarefully peel off the two of the rear anti-vibration rubber feet.\nThese are held in place with adhesive tape. Keep in mind that they will need to be reused, so store them carefully in the meantime.\nSome early units may have anti-vibration feet with a different design. In that case, peel off only part of the bottom to allow the profiles to be separated.", "In case you will be replacing one of the front Z motors, the bottom frame will need to be partially disassembled and two of the rubber feet removed.\nCarefully peel off the two of the rear anti-vibration rubber feet.\nThese are held in place with adhesive tape. Keep in mind that they will need to be reused, so store them carefully in the meantime.\nSome early units may have anti-vibration feet with a different design. In that case, peel off only part of the bottom to allow the profiles to be separated.", "In case you will be replacing one of the front Z motors, the bottom frame will need to be partially disassembled and two of the rubber feet removed.\nCarefully peel off the two of the rear anti-vibration rubber feet.\nThese are held in place with adhesive tape. Keep in mind that they will need to be reused, so store them carefully in the meantime.\nSome early units may have anti-vibration feet with a different design. In that case, peel off only part of the bottom to allow the profiles to be separated."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1038326", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/80bd4e8a426528584e46511697513e6d_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/80bd4e8a426528584e46511697513e6d_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1038447, 1038329, 1038330, 1038405]}, {"id": 1038457, "number": 10, "webNumber": 11, "title": ["底部の配線束を解放する", "Cable Bundle Release", "Cable Bundle Release", "Cable Bundle Release"], "body": ["フレームに配線束を固定している結束バンドを、ケーブルから刃を離して慎重に切り取ります。切ったバンドは廃棄し、後で新しい3本を使います。ケーブルの被覆を傷つけません。", "Carefully cut off the zip-ties holding the cable bundle to the printer’s frame.\nProceed carefully to prevent damaging the cables!", "Carefully cut off the zip-ties holding the cable bundle to the printer’s frame.\nProceed carefully to prevent damaging the cables!", "Carefully cut off the zip-ties holding the cable bundle to the printer’s frame.\nProceed carefully to prevent damaging the cables!"], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1038457", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/47b4677dd40cfb92d1cb62c957edefe4_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/47b4677dd40cfb92d1cb62c957edefe4_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1038458, 1038459]}, {"id": 1038493, "number": 11, "webNumber": 12, "title": ["splitterの押し込みピンを確認する", "Splitter Removal 1", "Splitter Removal 1", "Splitter Removal 1"], "body": ["Stepper Splitter基板は2本の押し込みピンで底部フレームに固定されています。各ピンには基板を固定する爪と板金を固定する爪があります。先細ペンチで爪をつまめる向きにし、無理な力を加えません。", "A stepper splitter board is attached to the bottom frame with two push pins.\nThe push pins have plastic hooks that can be released using needle-nose pliers.\nEach push pin has two sets of hooks: one secures the board, and the other secures it to the sheet metal profile.\nTo release the hooks, position the push pin so the pliers can effectively grip the hooks, then pull the push pin out to release it.", "A stepper splitter board is attached to the bottom frame with two push pins.\nThe push pins have plastic hooks that can be released using needle-nose pliers.\nEach push pin has two sets of hooks: one secures the board, and the other secures it to the sheet metal profile.\nTo release the hooks, position the push pin so the pliers can effectively grip the hooks, then pull the push pin out to release it.", "A stepper splitter board is attached to the bottom frame with two push pins.\nThe push pins have plastic hooks that can be released using needle-nose pliers.\nEach push pin has two sets of hooks: one secures the board, and the other secures it to the sheet metal profile.\nTo release the hooks, position the push pin so the pliers can effectively grip the hooks, then pull the push pin out to release it."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1038493", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/d313b5c7f1f19444ba52b237c6ab69ac_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/d313b5c7f1f19444ba52b237c6ab69ac_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/4b7d24b5eb49cbaa1496e07d074209a3_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/4b7d24b5eb49cbaa1496e07d074209a3_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1038494, 1038495, 1038496, 1038497]}, {"id": 1038545, "number": 12, "webNumber": 13, "title": ["splitterを2本のピンから外す", "Splitter Removal 2", "Splitter Removal 2", "Splitter Removal 2"], "body": ["爪をつまんで基板からピンを外し、次に板金側の爪も解除してピンを引き抜きます。2本とも同じ方法で外し、基板を配線の届く範囲でよけます。難しい場合は無理にピンを抜かず、基板を取り付けたまま端子を外す方法も公式に示されています。", "Proceed carefully to prevent any damage to the connectors. If you have difficulty removing the push pins, do not force them. The cables can still be disconnected with the splitter board attached, though space and cable length will be limited.\nPush the hooks on the push pin together, then carefully disengage it from the splitter board.\nThen, disengage the push pin from the sheet metal profile, while pulling it out.\nUsing the same technique, remove both push pins, releasing the splitter board.", "Proceed carefully to prevent any damage to the connectors. If you have difficulty removing the push pins, do not force them. The cables can still be disconnected with the splitter board attached, though space and cable length will be limited.\nPush the hooks on the push pin together, then carefully disengage it from the splitter board.\nThen, disengage the push pin from the sheet metal profile, while pulling it out.\nUsing the same technique, remove both push pins, releasing the splitter board.", "Proceed carefully to prevent any damage to the connectors. If you have difficulty removing the push pins, do not force them. The cables can still be disconnected with the splitter board attached, though space and cable length will be limited.\nPush the hooks on the push pin together, then carefully disengage it from the splitter board.\nThen, disengage the push pin from the sheet metal profile, while pulling it out.\nUsing the same technique, remove both push pins, releasing the splitter board."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1038545", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/b7cccf20eb70053d53da8b04e35e7bdf_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/b7cccf20eb70053d53da8b04e35e7bdf_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/ed923170124967afe0ec731f6346f2a6_painted-534x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/ed923170124967afe0ec731f6346f2a6_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1038546, 1038547, 1038548, 1038549]}, {"id": 1038587, "number": 13, "webNumber": 14, "title": ["後側モーターを抜線し、固定ねじ4本を外す", "Rear Z Motor Removal 1", "Rear Z Motor Removal 1", "Rear Z Motor Removal 1"], "body": ["後側Zモーターを交換します。前側だけを交換する場合は前側のフレーム分解へ進みます。splitterの『Z R』端子の安全ラッチを押して、後側モーターのコネクターを抜きます。本体内側から、モーターをシャーシへ固定するM3×8ねじ4本を1本ずつ外します。", "First, we will be replacing the rear Z motor.\nIf you need to replace one of the front motors only, skip ahead to the appropriate step.\nDisconnect the rear Z motor from the splitter board. The connector is labeled as \"Z R\"\nNote that there is a safety latch on the connector, which must be pressed in order to release the plug.\nOn the inside of the printer, remove the 4 M3x8 screws holding the motor to the chassis.", "First, we will be replacing the rear Z motor.\nIf you need to replace one of the front motors only, skip ahead to the appropriate step.\nDisconnect the rear Z motor from the splitter board. The connector is labeled as \"Z R\"\nNote that there is a safety latch on the connector, which must be pressed in order to release the plug.\nOn the inside of the printer, remove the 4 M3x8 screws holding the motor to the chassis.", "First, we will be replacing the rear Z motor.\nIf you need to replace one of the front motors only, skip ahead to the appropriate step.\nDisconnect the rear Z motor from the splitter board. The connector is labeled as \"Z R\"\nNote that there is a safety latch on the connector, which must be pressed in order to release the plug.\nOn the inside of the printer, remove the 4 M3x8 screws holding the motor to the chassis."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1038587", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/54031cb0460e94135ca7d48f33950351_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/54031cb0460e94135ca7d48f33950351_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/e4612f2208837e0ef3148462beb55995_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/e4612f2208837e0ef3148462beb55995_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1038588, 1038589, 1038590, 1038621]}, {"id": 1038633, "number": 14, "webNumber": 15, "title": ["後側のねじ軸を外し、モーターを抜き取る", "Rear Z Motor Removal 2", "Rear Z Motor Removal 2", "Rear Z Motor Removal 2"], "body": ["他の2個のモーターとフレームでベッドを保持したまま、後側モーターのねじ軸を反時計回りに回してベッドキャリッジのナットから外します。本体の底側からモーターと付属ケーブル全体を抜き取ります。", "Turn the motor shaft counter-clockwise to disengage it from the heatbed carriage.\nOn the bottom of the printer, pull the motor out.", "Turn the motor shaft counter-clockwise to disengage it from the heatbed carriage.\nOn the bottom of the printer, pull the motor out.", "Turn the motor shaft counter-clockwise to disengage it from the heatbed carriage.\nOn the bottom of the printer, pull the motor out."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1038633", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/159fe0f7ca71256b251ff8316f368d82_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/159fe0f7ca71256b251ff8316f368d82_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/1c50e2be63c247dffb78fa3fa90bf47d_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/1c50e2be63c247dffb78fa3fa90bf47d_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1038634, 1038635]}, {"id": 1038659, "number": 15, "webNumber": 16, "title": ["後側のマウントとワッシャーを再使用する", "Rear Motor Disassembly", "Rear Motor Disassembly", "Rear Motor Disassembly"], "body": ["取り出したモーター一式のM3×8ねじ4本を外し、樹脂製Zモーターマウントを取り外します。透明のモーターワッシャーパッドがある仕様では、それも取り外して再使用します。実機にパッドがない仕様では追加せず、パッドの工程を省略します。", "On the motor assembly, remove the Z-motor mount plastic part held by four M3x8 screws.\nRemove the plastic washer from the motor.\nIf your printer version does not have the transparent motor washer pad, simply ignore this part and continue with the procedure.", "On the motor assembly, remove the Z-motor mount plastic part held by four M3x8 screws.\nRemove the plastic washer from the motor.\nIf your printer version does not have the transparent motor washer pad, simply ignore this part and continue with the procedure.", "On the motor assembly, remove the Z-motor mount plastic part held by four M3x8 screws.\nRemove the plastic washer from the motor.\nIf your printer version does not have the transparent motor washer pad, simply ignore this part and continue with the procedure."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1038659", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2025/11/25bcf193a469ab5fc7cd96acf0f7b5aa_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2025/11/25bcf193a469ab5fc7cd96acf0f7b5aa_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/e874c6ec1e1904786b7cb78f39109543_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/e874c6ec1e1904786b7cb78f39109543_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1038660, 1038661, 1306544]}, {"id": 1038684, "number": 16, "webNumber": 17, "title": ["新しい後側モーター1個を用意する", "Rear Motor Preparation", "Rear Motor Preparation", "Rear Motor Preparation"], "body": ["『Z-Axis Right』と表示された新しい後側Zモーター1個を用意します。前側用LEFTとはケーブル長が異なります。古いモーターとそのケーブルは新しい部品と混ぜず、交換済みとして別に保管します。", "For the following steps, prepare:\nNew Rear Z Motor (1x)\nThe motor is labeled Z-Axis Right, as it is the same type used in the MK4/S printer series.", "For the following steps, prepare:\nNew Rear Z Motor (1x)\nThe motor is labeled Z-Axis Right, as it is the same type used in the MK4/S printer series.", "For the following steps, prepare:\nNew Rear Z Motor (1x)\nThe motor is labeled Z-Axis Right, as it is the same type used in the MK4/S printer series."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1038684", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/ca7a07276d56eb20a1a72ebb918af444-533x400.jpg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/ca7a07276d56eb20a1a72ebb918af444.jpg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1038685, 1038686, 1038687]}, {"id": 1038716, "number": 17, "webNumber": 18, "title": ["後側マウントを新しいモーターへ移す", "Rear Motor Assembly", "Rear Motor Assembly", "Rear Motor Assembly"], "body": ["パッドがある仕様では再使用するワッシャーを新しいモーターへ載せます。元の樹脂マウントの向きを合わせ、取り外したM3×8ねじ4本で固定します。パッドなし仕様へ新しいスペーサーを勝手に追加しません。", "Place the washer onto the motor.\nIf your printer version does not have the transparent motor washer pad, simply ignore this part and continue with the procedure.\nAlign the motor mount plastic part with the aseembly and fix it in place using the four M3x8 screws.", "Place the washer onto the motor.\nIf your printer version does not have the transparent motor washer pad, simply ignore this part and continue with the procedure.\nAlign the motor mount plastic part with the aseembly and fix it in place using the four M3x8 screws.", "Place the washer onto the motor.\nIf your printer version does not have the transparent motor washer pad, simply ignore this part and continue with the procedure.\nAlign the motor mount plastic part with the aseembly and fix it in place using the four M3x8 screws."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1038716", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/e874c6ec1e1904786b7cb78f39109543_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/e874c6ec1e1904786b7cb78f39109543_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2025/11/25bcf193a469ab5fc7cd96acf0f7b5aa_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2025/11/25bcf193a469ab5fc7cd96acf0f7b5aa_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1038717, 1306552, 1038718]}, {"id": 1039661, "number": 18, "webNumber": 19, "title": ["後側モーターを差し込み、ねじ軸を掛ける", "Rear Motor Installation", "Rear Motor Installation", "Rear Motor Installation"], "body": ["後側モーターを対応する開口へ入れ、ねじ軸とベッドキャリッジのナットを合わせてねじ込みます。モーターが完全に着座し、ベッドキャリッジが本体フレームに対して直角になるまで適切な位置へねじ込みます。ケーブルは下向きにします。", "Insert the motor into the corresponding opening.\nAlign the threaded rod with the nut in the heatbed carriage and start threading it in.\nThread in the appropriate section of the rod until the motor is fully seated and the heatbed carriage is perpendicular to the printer’s frame.\nOrient the motor so that the cable is pointing downward.", "Insert the motor into the corresponding opening.\nAlign the threaded rod with the nut in the heatbed carriage and start threading it in.\nThread in the appropriate section of the rod until the motor is fully seated and the heatbed carriage is perpendicular to the printer’s frame.\nOrient the motor so that the cable is pointing downward.", "Insert the motor into the corresponding opening.\nAlign the threaded rod with the nut in the heatbed carriage and start threading it in.\nThread in the appropriate section of the rod until the motor is fully seated and the heatbed carriage is perpendicular to the printer’s frame.\nOrient the motor so that the cable is pointing downward."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1039661", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/e50554ceb89e285562b395ab2b41cd38_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/e50554ceb89e285562b395ab2b41cd38_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/0ae25af52e43ad112dbb455de33b3ed5_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/0ae25af52e43ad112dbb455de33b3ed5_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/39da803558074a0ce32eb3f7809a1302_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/39da803558074a0ce32eb3f7809a1302_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1039662, 1039663, 1039664, 1039665]}, {"id": 1039744, "number": 19, "webNumber": 20, "title": ["後側の固定ねじとZ R接続を戻す", "Rear Motor Attachment", "Rear Motor Attachment", "Rear Motor Attachment"], "body": ["モーターの着座とベッドの直角を確認し、本体内側からM3×8ねじ4本で固定します。樹脂へ直接ねじ込むため締めすぎず、最後は六角レンチの短い側を持って締めます。モーターのコネクターをsplitterの対応するZ R端子へ奥まで差し込みます。", "Once the heatbed carriage is aligned with the printer’s frame and the motor is fully seated, proceed with attaching the motor.\nOn the inside of the printer, fix the motor in place using the four M3x8 screws.\nDo not overtighten the screws, as they thread directly into the plastic part. For a final tightening, use the shorter part of the key as a handle to apply the correct amount of torque.\nPlug the motor into the corresponding connector on the stepper splitter board.", "Once the heatbed carriage is aligned with the printer’s frame and the motor is fully seated, proceed with attaching the motor.\nOn the inside of the printer, fix the motor in place using the four M3x8 screws.\nDo not overtighten the screws, as they thread directly into the plastic part. For a final tightening, use the shorter part of the key as a handle to apply the correct amount of torque.\nPlug the motor into the corresponding connector on the stepper splitter board.", "Once the heatbed carriage is aligned with the printer’s frame and the motor is fully seated, proceed with attaching the motor.\nOn the inside of the printer, fix the motor in place using the four M3x8 screws.\nDo not overtighten the screws, as they thread directly into the plastic part. For a final tightening, use the shorter part of the key as a handle to apply the correct amount of torque.\nPlug the motor into the corresponding connector on the stepper splitter board."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1039744", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/0dfbd69ef3d5f797453cda6c20d75f83_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/0dfbd69ef3d5f797453cda6c20d75f83_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/e4612f2208837e0ef3148462beb55995_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/e4612f2208837e0ef3148462beb55995_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/54031cb0460e94135ca7d48f33950351_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/54031cb0460e94135ca7d48f33950351_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1039745, 1039760, 1039761, 1039776]}, {"id": 1039791, "number": 20, "webNumber": 21, "title": ["底部フレームの6本のねじを外す", "Bottom Frame Disassembly", "Bottom Frame Disassembly", "Bottom Frame Disassembly"], "body": ["前側モーターを交換するため底部フレームを外します。底面の指定M3×4rTねじ2本、左側の指定2本、前面の指定2本を1本ずつ外して保管します。前側2個を交換する場合も、各モーターの交換を1個ずつ最後まで済ませます。", "In the next steps, we will replace the front Z motor. The procedure is the same for either front Z motor. If you are replacing both, repeat the same steps for each side.\nWe will need to remove the bottom part of the frame.\nRemove two marked M3x4rT screws on the bottom.\nRemove the two marked M3x4rT screws on the left side.\nRemove two marked M3x4rT screws on the front of the printer.", "In the next steps, we will replace the front Z motor. The procedure is the same for either front Z motor. If you are replacing both, repeat the same steps for each side.\nWe will need to remove the bottom part of the frame.\nRemove two marked M3x4rT screws on the bottom.\nRemove the two marked M3x4rT screws on the left side.\nRemove two marked M3x4rT screws on the front of the printer.", "In the next steps, we will replace the front Z motor. The procedure is the same for either front Z motor. If you are replacing both, repeat the same steps for each side.\nWe will need to remove the bottom part of the frame.\nRemove two marked M3x4rT screws on the bottom.\nRemove the two marked M3x4rT screws on the left side.\nRemove two marked M3x4rT screws on the front of the printer."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1039791", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/26f24d14f0a6348b7fbdc64351aae17e_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/26f24d14f0a6348b7fbdc64351aae17e_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/c1f4b78e4f6a3a7fe37025ea538e4da3_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/c1f4b78e4f6a3a7fe37025ea538e4da3_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/cc13482dccee8fa51527573dd22c17ff_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/cc13482dccee8fa51527573dd22c17ff_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1039792, 1039793, 1039794, 1039795, 1039796]}, {"id": 1039843, "number": 21, "webNumber": 22, "title": ["右側のリベット3個とねじ2本を外す", "Bottom Frame Disassembly 2", "Bottom Frame Disassembly 2", "Bottom Frame Disassembly 2"], "body": ["右側の底部フレームを固定するナイロンリベット3個を、ロックを解除して抜きます。続いて底部フレームを固定するM3×4rTねじ2本を外します。", "On the right side of the printer, remove the three Nylon rivets holding the bottom part of the frame.\nRemove the two M3x4rT screws holding the bottom part of the frame.", "On the right side of the printer, remove the three Nylon rivets holding the bottom part of the frame.\nRemove the two M3x4rT screws holding the bottom part of the frame.", "On the right side of the printer, remove the three Nylon rivets holding the bottom part of the frame.\nRemove the two M3x4rT screws holding the bottom part of the frame."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1039843", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/1da9a2d33e4cccef2afc2b06ffabf16a_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/1da9a2d33e4cccef2afc2b06ffabf16a_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/7e021d3b3ac5bdaf98eee98bdbf4de89_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/7e021d3b3ac5bdaf98eee98bdbf4de89_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1039844, 1039845]}, {"id": 1039871, "number": 22, "webNumber": 23, "title": ["LCDの2本の端子を開口へ戻し、フレームを外す", "Bottom Frame Disassembly 3", "Bottom Frame Disassembly 3", "Bottom Frame Disassembly 3"], "body": ["底部フレームを本体から離します。xLCDのメイン端子とFE接地Faston端子を中央の開口へ慎重に通してフレームから解放します。ケーブルを引っ掛けず、フレームを取り出して再組み立てまで保管します。", "Pull the bottom part of the frame away from the printer.\nPush the xLCD connectors through the opening to free them from the bottom frame.\nCarefully remove the bottom frame and store it away for later re-assembly.", "Pull the bottom part of the frame away from the printer.\nPush the xLCD connectors through the opening to free them from the bottom frame.\nCarefully remove the bottom frame and store it away for later re-assembly.", "Pull the bottom part of the frame away from the printer.\nPush the xLCD connectors through the opening to free them from the bottom frame.\nCarefully remove the bottom frame and store it away for later re-assembly."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1039871", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/7ab1283dcd4fbe836ccd957bc3ff4a2a_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/7ab1283dcd4fbe836ccd957bc3ff4a2a_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/e02163b9bfa97110c76222fd40233e12_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/e02163b9bfa97110c76222fd40233e12_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1039872, 1039873, 1039874]}, {"id": 1039917, "number": 23, "webNumber": 24, "title": ["前側モーターの固定ねじ4本と端子を外す", "Front Z Motor Removal", "Front Z Motor Removal", "Front Z Motor Removal"], "body": ["対象の前側モーターを確認します。公式は前左を示し、前右も同じ手順です。本体内側からM3×8ねじ4本を1本ずつ外し、対応するモーターのsplitter端子をラッチ解除して抜きます。反対側と後側のモーターは取り付けたまま残します。", "Now we will show the removal process for the front left motor. The procedure for the front right motor is the same.\nThe procedure for the front right motor is the same.\nOn the inside of the printer, remove the four M3x8 screws holding the motor.\nDisconnect the motor from the splitter board.", "Now we will show the removal process for the front left motor. The procedure for the front right motor is the same.\nThe procedure for the front right motor is the same.\nOn the inside of the printer, remove the four M3x8 screws holding the motor.\nDisconnect the motor from the splitter board.", "Now we will show the removal process for the front left motor. The procedure for the front right motor is the same.\nThe procedure for the front right motor is the same.\nOn the inside of the printer, remove the four M3x8 screws holding the motor.\nDisconnect the motor from the splitter board."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1039917", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/392f7afeeb45f509738d4da93e4941d7_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/392f7afeeb45f509738d4da93e4941d7_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/4d6bbb7ce0c68290459be16be52faf02_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/4d6bbb7ce0c68290459be16be52faf02_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/de61833f51f96296317e44b9c3506d49_painted-533x400.png", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/de61833f51f96296317e44b9c3506d49_painted.png", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1039918, 1039919, 1039920, 1039921]}, {"id": 1040358, "number": 24, "webNumber": 25, "title": ["前側のねじ軸を外し、モーターを抜く", "Front Z Motor Removal 2", "Front Z Motor Removal 2", "Front Z Motor Removal 2"], "body": ["対象モーターのねじ軸を反時計回りに回し、ベッドキャリッジのナットから外します。モーターとそのケーブル全体を底側へ抜き取ります。ベッドを支える他のモーターまで同時に外しません。", "Rotate the motor shaft counter-clockwise to disengage it from the heatbed carriage.\nRemove the motor by pulling it out.", "Rotate the motor shaft counter-clockwise to disengage it from the heatbed carriage.\nRemove the motor by pulling it out.", "Rotate the motor shaft counter-clockwise to disengage it from the heatbed carriage.\nRemove the motor by pulling it out."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1040358", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/6670ec3370b4455cf782145c2374d677_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/6670ec3370b4455cf782145c2374d677_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/ffed545f8dd1183baf554b4a6287fafd_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/ffed545f8dd1183baf554b4a6287fafd_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1040359, 1040360]}, {"id": 1040382, "number": 25, "webNumber": 26, "title": ["前側マウントとワッシャーを外す", "Front Motor Disassembly", "Front Motor Disassembly", "Front Motor Disassembly"], "body": ["モーター一式からM3×8ねじ4本を外し、再使用する樹脂マウントを外します。透明ワッシャーパッドがある仕様では、それも外して保管します。パッドがない実機ではこの部品の工程を省略します。", "On the motor assembly, remove the Z-motor mount plastic part held by four M3x8 screws.\nRemove the plastic washer from the motor.\nIf your printer version does not have the transparent motor washer pad, simply ignore this part and continue with the procedure.", "On the motor assembly, remove the Z-motor mount plastic part held by four M3x8 screws.\nRemove the plastic washer from the motor.\nIf your printer version does not have the transparent motor washer pad, simply ignore this part and continue with the procedure.", "On the motor assembly, remove the Z-motor mount plastic part held by four M3x8 screws.\nRemove the plastic washer from the motor.\nIf your printer version does not have the transparent motor washer pad, simply ignore this part and continue with the procedure."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1040382", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2025/11/25bcf193a469ab5fc7cd96acf0f7b5aa_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2025/11/25bcf193a469ab5fc7cd96acf0f7b5aa_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/e874c6ec1e1904786b7cb78f39109543_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/e874c6ec1e1904786b7cb78f39109543_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1040383, 1040384, 1306560]}, {"id": 1040407, "number": 26, "webNumber": 27, "title": ["新しい前側モーターを用意する", "Front Motor Preparation", "Front Motor Preparation", "Front Motor Preparation"], "body": ["『Z-Axis Left』と表示された短いケーブルの前側Zモーターを、交換する側ごとに1個用意します。前側2個を交換する場合の合計は2個です。古いモーターとケーブルは新しい部品と区別します。", "For the following steps, prepare:\nNew Front Z Motor (1 or 2x)\nThe motor is labeled Z-Axis Left, as it is the same type used in the MK4/S printer series.", "For the following steps, prepare:\nNew Front Z Motor (1 or 2x)\nThe motor is labeled Z-Axis Left, as it is the same type used in the MK4/S printer series.", "For the following steps, prepare:\nNew Front Z Motor (1 or 2x)\nThe motor is labeled Z-Axis Left, as it is the same type used in the MK4/S printer series."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1040407", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/fe532dd9d45e018cb64aa40fe7448e4e-533x400.jpg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/fe532dd9d45e018cb64aa40fe7448e4e.jpg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1040408, 1040409, 1040410]}, {"id": 1040441, "number": 27, "webNumber": 28, "title": ["前側マウントを新しいモーターへ移す", "Front Motor Assembly", "Front Motor Assembly", "Front Motor Assembly"], "body": ["パッドがある仕様では元のワッシャーを新しいモーターへ載せます。元の樹脂マウントを合わせ、M3×8ねじ4本で固定します。パッドなし仕様ではパッドを追加しません。", "Place the washer onto the motor.\nIf your printer version does not have the transparent motor washer pad, simply ignore this part and continue with the procedure.\nAlign the motor mount plastic part with the aseembly and fix it in place using the four M3x8 screws.", "Place the washer onto the motor.\nIf your printer version does not have the transparent motor washer pad, simply ignore this part and continue with the procedure.\nAlign the motor mount plastic part with the aseembly and fix it in place using the four M3x8 screws.", "Place the washer onto the motor.\nIf your printer version does not have the transparent motor washer pad, simply ignore this part and continue with the procedure.\nAlign the motor mount plastic part with the aseembly and fix it in place using the four M3x8 screws."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1040441", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/e874c6ec1e1904786b7cb78f39109543_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/e874c6ec1e1904786b7cb78f39109543_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2025/11/25bcf193a469ab5fc7cd96acf0f7b5aa_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2025/11/25bcf193a469ab5fc7cd96acf0f7b5aa_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1040442, 1306568, 1040443]}, {"id": 1040469, "number": 28, "webNumber": 29, "title": ["前側モーターを入れ、時計回りにねじ込む", "Front Motor Installation", "Front Motor Installation", "Front Motor Installation"], "body": ["対象の開口へモーターのねじ軸を通します。軸を時計回りに回してベッド側のナットへ掛け、モーターが完全に着座し、ベッドキャリッジがフレームに対して直角になるまでねじ込みます。", "Insert the motor shaft through the corresponding opening.\nEngage the threaded rod into the heatbed assembly by rotating it clockwise.\nThread in the appropriate section of the rod until the motor is fully seated and the heatbed carriage is perpendicular to the printer’s frame.", "Insert the motor shaft through the corresponding opening.\nEngage the threaded rod into the heatbed assembly by rotating it clockwise.\nThread in the appropriate section of the rod until the motor is fully seated and the heatbed carriage is perpendicular to the printer’s frame.", "Insert the motor shaft through the corresponding opening.\nEngage the threaded rod into the heatbed assembly by rotating it clockwise.\nThread in the appropriate section of the rod until the motor is fully seated and the heatbed carriage is perpendicular to the printer’s frame."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1040469", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/94c4bbe6b4cabb2ccbe8cfe8d35099f0_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/94c4bbe6b4cabb2ccbe8cfe8d35099f0_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/5ae7a0b946e1a131e036b0d498d9746f_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/5ae7a0b946e1a131e036b0d498d9746f_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1040470, 1040471, 1040493]}, {"id": 1040505, "number": 29, "webNumber": 30, "title": ["前側を4本で固定し、対応端子へ接続する", "Front Motor Attachment", "Front Motor Attachment", "Front Motor Attachment"], "body": ["着座と直角を確認してから、本体内側のM3×8ねじ4本でモーターを固定します。樹脂部を締めすぎないようレンチの短い側を持って仕上げます。対応するsplitter端子へモーターを接続します。もう一方も交換する場合は、このモーターを固定・接続し終えてから同じ7工程を繰り返します。", "Once the heatbed carriage is aligned with the printer’s frame and the motor is fully seated, proceed with attaching the motor.\nOn the inside of the printer, fix the motor in place using the four M3x8 screws.\nDo not overtighten the screws, as they thread directly into the plastic part. For a final tightening, use the shorter part of the key as a handle to apply the correct amount of torque.\nPlug the motor into the corresponding connector on the stepper splitter board.", "Once the heatbed carriage is aligned with the printer’s frame and the motor is fully seated, proceed with attaching the motor.\nOn the inside of the printer, fix the motor in place using the four M3x8 screws.\nDo not overtighten the screws, as they thread directly into the plastic part. For a final tightening, use the shorter part of the key as a handle to apply the correct amount of torque.\nPlug the motor into the corresponding connector on the stepper splitter board.", "Once the heatbed carriage is aligned with the printer’s frame and the motor is fully seated, proceed with attaching the motor.\nOn the inside of the printer, fix the motor in place using the four M3x8 screws.\nDo not overtighten the screws, as they thread directly into the plastic part. For a final tightening, use the shorter part of the key as a handle to apply the correct amount of torque.\nPlug the motor into the corresponding connector on the stepper splitter board."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1040505", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/d8e95482535ef5c5b8b385f0298bd55b_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/d8e95482535ef5c5b8b385f0298bd55b_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/4d6bbb7ce0c68290459be16be52faf02_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/4d6bbb7ce0c68290459be16be52faf02_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/de61833f51f96296317e44b9c3506d49_painted-533x400.png", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/de61833f51f96296317e44b9c3506d49_painted.png", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1040506, 1040507, 1040508, 1040509]}, {"id": 1040551, "number": 30, "webNumber": 31, "title": ["splitterの4接続を照合する", "Motor Connection Check", "Motor Connection Check", "Motor Connection Check"], "body": ["xBuddyからのケーブルは、splitter基板の斜めに切り欠かれた縁に近い端子へ接続します。残る3端子が3個のZモーターです。公式の接続写真と、後側Z Rおよび前側2本の接続先を個別に照合します。", "Verify the proper connection of the motors, as seen in the picture.\nThe cable connection from the xBuddy board is connected into the plug near the beveled edge of the Splitter board.\nThe motor cables are connected to the remaining three connectors.", "Verify the proper connection of the motors, as seen in the picture.\nThe cable connection from the xBuddy board is connected into the plug near the beveled edge of the Splitter board.\nThe motor cables are connected to the remaining three connectors.", "Verify the proper connection of the motors, as seen in the picture.\nThe cable connection from the xBuddy board is connected into the plug near the beveled edge of the Splitter board.\nThe motor cables are connected to the remaining three connectors."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1040551", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/a50ca36aab7d07e4caf6a81cc22548cb_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/a50ca36aab7d07e4caf6a81cc22548cb_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1040552, 1040553, 1040554]}, {"id": 1040587, "number": 31, "webNumber": 32, "title": ["底部フレームの開口へLCD端子を通す", "Bottom Frame Assembly", "Bottom Frame Assembly", "Bottom Frame Assembly"], "body": ["保管した底部フレームを本体へ合わせます。xLCDのメイン端子とFE接地Faston端子を、前面中央の開口から外側へ通します。2本とも通したことを確認します。", "Take the previously removed part of the bottom assembly and align it with the printer.\nPush the xLCD connector and the FE grounding Faston connector through the front center opening.", "Take the previously removed part of the bottom assembly and align it with the printer.\nPush the xLCD connector and the FE grounding Faston connector through the front center opening.", "Take the previously removed part of the bottom assembly and align it with the printer.\nPush the xLCD connector and the FE grounding Faston connector through the front center opening."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1040587", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/684bc77f2336b668e7a7adf582d05b00_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/684bc77f2336b668e7a7adf582d05b00_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/4b0ddfb6f0300669441df7b3ab2fa914_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/4b0ddfb6f0300669441df7b3ab2fa914_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1040588, 1040589]}, {"id": 1040617, "number": 32, "webNumber": 33, "title": ["フレームの重なりを合わせる", "Bottom Frame Alignment", "Bottom Frame Alignment", "Bottom Frame Alignment"], "body": ["前面では底部フレームをシャーシの上へ重ねます。右側ではシャーシと側板の間に挟み、右奥では取り付け済みパネルの裏側へ入れます。左側では取り付け済みパネルの上へ重ねます。配線を挟まず正確に合わせます。", "Start precisely aligning the frame with the printer chassis.\nAt the front, the bottom frame should rest over the printer chassis.\nOn the right side, the bottom frame must be sandwiched between the printer chassis and the side panel.\nOn the right far side, the bottom frame must sit behind the mounted panels.\nOn the left side, the bottom frame goes over the mounted panels.", "Start precisely aligning the frame with the printer chassis.\nAt the front, the bottom frame should rest over the printer chassis.\nOn the right side, the bottom frame must be sandwiched between the printer chassis and the side panel.\nOn the right far side, the bottom frame must sit behind the mounted panels.\nOn the left side, the bottom frame goes over the mounted panels.", "Start precisely aligning the frame with the printer chassis.\nAt the front, the bottom frame should rest over the printer chassis.\nOn the right side, the bottom frame must be sandwiched between the printer chassis and the side panel.\nOn the right far side, the bottom frame must sit behind the mounted panels.\nOn the left side, the bottom frame goes over the mounted panels."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1040617", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/4413bf32cacc7438f5dd2853328fd69e_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/4413bf32cacc7438f5dd2853328fd69e_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/d2ed08a53aafeb40076c8e3c32d15276_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/d2ed08a53aafeb40076c8e3c32d15276_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/3c773b80a230bf273c82a34882a759ce_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/3c773b80a230bf273c82a34882a759ce_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1040618, 1040619, 1040620, 1040621, 1040622]}, {"id": 1040665, "number": 33, "webNumber": 34, "title": ["右側と前面を固定する", "Bottom Frame Attachment", "Bottom Frame Attachment", "Bottom Frame Attachment"], "body": ["右側をナイロンリベット3個で固定し、対応するM3×4rTねじ2本を戻します。前面の対応する開口にもM3×4rTねじ2本を取り付けます。", "On the right side of the printer, fix the parts together using three Nylon rivets.\nInstall the two M3x4rT screws into the corresponding openings to fix the parts together.\nInstall two M3x4rT screws into the front openings.", "On the right side of the printer, fix the parts together using three Nylon rivets.\nInstall the two M3x4rT screws into the corresponding openings to fix the parts together.\nInstall two M3x4rT screws into the front openings.", "On the right side of the printer, fix the parts together using three Nylon rivets.\nInstall the two M3x4rT screws into the corresponding openings to fix the parts together.\nInstall two M3x4rT screws into the front openings."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1040665", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/1da9a2d33e4cccef2afc2b06ffabf16a_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/1da9a2d33e4cccef2afc2b06ffabf16a_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/7e021d3b3ac5bdaf98eee98bdbf4de89_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/7e021d3b3ac5bdaf98eee98bdbf4de89_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/cc13482dccee8fa51527573dd22c17ff_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/cc13482dccee8fa51527573dd22c17ff_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1040666, 1040667, 1040689]}, {"id": 1040697, "number": 34, "webNumber": 35, "title": ["左側・底面・ゴム足を戻す", "Bottom Frame Attachment 2", "Bottom Frame Attachment 2", "Bottom Frame Attachment 2"], "body": ["左側へM3×4rTねじ2本、奥側の底面へ残りのM3×4rTねじ2本を戻します。保管した防振ゴム足も元の位置へ取り付けます。", "On the left side, install the two M3x4rT screws into the corresponding openings.\nOn the far bottom side of the printer, install the last two M3x4rT screws.\nRe-install the anti-vibration rubber feet.", "On the left side, install the two M3x4rT screws into the corresponding openings.\nOn the far bottom side of the printer, install the last two M3x4rT screws.\nRe-install the anti-vibration rubber feet.", "On the left side, install the two M3x4rT screws into the corresponding openings.\nOn the far bottom side of the printer, install the last two M3x4rT screws.\nRe-install the anti-vibration rubber feet."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1040697", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/c1f4b78e4f6a3a7fe37025ea538e4da3_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/c1f4b78e4f6a3a7fe37025ea538e4da3_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/26f24d14f0a6348b7fbdc64351aae17e_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/26f24d14f0a6348b7fbdc64351aae17e_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/80bd4e8a426528584e46511697513e6d_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/80bd4e8a426528584e46511697513e6d_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1040698, 1040699, 1040721]}, {"id": 1040733, "number": 35, "webNumber": 36, "title": ["splitterを2本の押し込みピンで戻す", "Splitter Installation", "Splitter Installation", "Splitter Installation"], "body": ["2本のsplitter固定ピンを対応する開口へ戻します。本体内側から基板をピンへ合わせ、クリックして固定されるまで押し込みます。接続済みケーブルへ無理な力を加えません。", "Re-install the two stepper splitter push pins into the corresponding openings.\nNow, we can re-clip the splitter board onto the push pins from the inside.\nPush the splitter board onto the push pins until it clicks into place.", "Re-install the two stepper splitter push pins into the corresponding openings.\nNow, we can re-clip the splitter board onto the push pins from the inside.\nPush the splitter board onto the push pins until it clicks into place.", "Re-install the two stepper splitter push pins into the corresponding openings.\nNow, we can re-clip the splitter board onto the push pins from the inside.\nPush the splitter board onto the push pins until it clicks into place."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1040733", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/3289cc1379b702f97952ad5394292c7f_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/3289cc1379b702f97952ad5394292c7f_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/d313b5c7f1f19444ba52b237c6ab69ac_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/d313b5c7f1f19444ba52b237c6ab69ac_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/3d58805dc944d3379163ec76d5202f78_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/3d58805dc944d3379163ec76d5202f78_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1040734, 1040735, 1040736]}, {"id": 1040767, "number": 36, "webNumber": 37, "title": ["新しい結束バンド3本でまとめる", "Cable Management", "Cable Management", "Cable Management"], "body": ["フレームの開口へ新しい結束バンド3本を通し、配線束を包みます。xLCD開口付近に十分なケーブル長を残し、締めすぎず軽くまとめて余りを切ります。古い切断済みバンドを再使用しません。", "Reinstall three new zip ties through the openings and wrap them around the cable bundle.\nMake sure there is enough cable length exposed near the xLCD opening.\nLoosely tighten the zip ties, then trim off the excess.", "Reinstall three new zip ties through the openings and wrap them around the cable bundle.\nMake sure there is enough cable length exposed near the xLCD opening.\nLoosely tighten the zip ties, then trim off the excess.", "Reinstall three new zip ties through the openings and wrap them around the cable bundle.\nMake sure there is enough cable length exposed near the xLCD opening.\nLoosely tighten the zip ties, then trim off the excess."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1040767", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/a016c74cb6adf4138cf4cb3b108ef05d_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/a016c74cb6adf4138cf4cb3b108ef05d_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/fa06fa8d295fe5c0399128dedd1f91c2_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/fa06fa8d295fe5c0399128dedd1f91c2_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/c489556ae975be5e049478320e062390_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/c489556ae975be5e049478320e062390_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1040768, 1040807, 1040797]}, {"id": 1040815, "number": 37, "webNumber": 38, "title": ["左側パネルをリベット11個で戻す", "Left Panel Installation", "Left Panel Installation", "Left Panel Installation"], "body": ["左側の板金パネルを元へ合わせ、保管したナイロンリベット11個を1個ずつ戻してロックします。ケーブルを板金の縁に挟まないことを確認します。", "Reinstall the left side panel onto the printer.\nFix the panel in place using the 11 Nylon rivets.", "Reinstall the left side panel onto the printer.\nFix the panel in place using the 11 Nylon rivets.", "Reinstall the left side panel onto the printer.\nFix the panel in place using the 11 Nylon rivets."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1040815", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/7eddd17d25cb54f8a7562417a4a83f7f_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/7eddd17d25cb54f8a7562417a4a83f7f_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1040816, 1040817]}, {"id": 1040841, "number": 38, "webNumber": 39, "title": ["xLCDのメインとFE接地を接続する", "xLCD Installation", "xLCD Installation", "xLCD Installation"], "body": ["xLCDへメイン端子を接続します。コネクターのラッチを、xLCD基板の三角印と同じ側へ向けます。向きが違うとxLCDは動作しません。FE接地線のFaston端子も接続します。", "Connect the main connector into the xLCD assembly.\nEnsure the latch on the connector is positioned on the same side as the triangle symbol on the xLCD board. Otherwise, the xLCD won't work.\nConnect the FE Grounding cable faston connector.", "Connect the main connector into the xLCD assembly.\nEnsure the latch on the connector is positioned on the same side as the triangle symbol on the xLCD board. Otherwise, the xLCD won't work.\nConnect the FE Grounding cable faston connector.", "Connect the main connector into the xLCD assembly.\nEnsure the latch on the connector is positioned on the same side as the triangle symbol on the xLCD board. Otherwise, the xLCD won't work.\nConnect the FE Grounding cable faston connector."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1040841", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2026/01/494fcb349b315758edf97aec7cf33bfb_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2026/01/494fcb349b315758edf97aec7cf33bfb_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2025/11/3940f8f3bd0c080bcbc5d90397ac7005-533x400.jpg", "original": "https://help.prusa3d.com/wp-content/uploads/2025/11/3940f8f3bd0c080bcbc5d90397ac7005.jpg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1040842, 1040843, 1040844]}, {"id": 1040873, "number": 39, "webNumber": 40, "title": ["xLCDを左フックから取り付ける", "xLCD Installation 2", "xLCD Installation 2", "xLCD Installation 2"], "body": ["xLCDを本体へ近づけ、右側を少し上げます。左側のベゼルを左のフレームへ掛け、右側をゆっくり下ろして右のフックも掛けます。底の両端が均等に着座していることを確認します。作業を終え、フレームを支えて本体を通常の姿勢へ戻します。", "Move the xLCD assembly towards the printer and raise its right side.\nHook the left side of the bezel onto the left profile of the printer.\nSlowly lower the right side into place as well.\nHook the right side of the bezel onto the right profile.\nEnsure the bezel is evenly seated at both ends along the bottom edge.", "Move the xLCD assembly towards the printer and raise its right side.\nHook the left side of the bezel onto the left profile of the printer.\nSlowly lower the right side into place as well.\nHook the right side of the bezel onto the right profile.\nEnsure the bezel is evenly seated at both ends along the bottom edge.", "Move the xLCD assembly towards the printer and raise its right side.\nHook the left side of the bezel onto the left profile of the printer.\nSlowly lower the right side into place as well.\nHook the right side of the bezel onto the right profile.\nEnsure the bezel is evenly seated at both ends along the bottom edge."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1040873", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2025/11/ac4b79ba0a760f03_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2025/11/ac4b79ba0a760f03_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2025/01/3dc82f650444482301f96d30454afd7b_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2025/01/3dc82f650444482301f96d30454afd7b_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1040874, 1040875, 1040876, 1040877, 1040878]}, {"id": 1040921, "number": 40, "webNumber": 41, "title": ["電源を接続し、起動する", "Printer Power Up", "Printer Power Up", "Printer Power Up"], "body": ["工具・取り外し部品・配線の挟み込みが残っていないことを確認します。電源コードを接続し、背面のスイッチで電源を入れます。", "Connect the printer to power.\nTurn the printer on using the switch on the back.", "Connect the printer to power.\nTurn the printer on using the switch on the back.", "Connect the printer to power.\nTurn the printer on using the switch on the back."], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1040921", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2025/11/c023a6b523f9b3c9f5dd84a1f84f102e_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2025/11/c023a6b523f9b3c9f5dd84a1f84f102e_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1040922, 1040923]}, {"id": 1040945, "number": 41, "webNumber": 42, "title": ["Auto Home・Move Z・Selftestを実行する", "Selftest", "Selftest", "Selftest"], "body": ["実機のControl → Auto Homeを実行します。次にControl → Move Axis → Move ZでZ軸が正しく動くことを確認します。最後にControl → Calibrations & TestsからSelftestを最初から実行し、合格してから使用を再開します。", "On the printer, visit the menu Control and trigger the Auto Home.\nGo to Control > Move Axis > Move Z and test if the Z Axis moves correctly.\nTo finish the repair, visit the menu Control -> Calibrations & Testsand run the Selftest from the start.\nAfter passing the Selftest, your printer is ready for use again. Hooray!", "On the printer, visit the menu Control and trigger the Auto Home.\nGo to Control > Move Axis > Move Z and test if the Z Axis moves correctly.\nTo finish the repair, visit the menu Control -> Calibrations & Testsand run the Selftest from the start.\nAfter passing the Selftest, your printer is ready for use again. Hooray!", "On the printer, visit the menu Control and trigger the Auto Home.\nGo to Control > Move Axis > Move Z and test if the Z Axis moves correctly.\nTo finish the repair, visit the menu Control -> Calibrations & Testsand run the Selftest from the start.\nAfter passing the Selftest, your printer is ready for use again. Hooray!"], "source": "https://help.prusa3d.com/guide/how-to-replace-z-motors-core-one_575994#1040945", "images": [{"url": "https://help.prusa3d.com/wp-content/uploads/2025/10/58002b89d9cf30684c18b50963872e57_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2025/10/58002b89d9cf30684c18b50963872e57_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2025/07/baf01ce12f144cffa0b627a2d88f5d75_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2025/07/baf01ce12f144cffa0b627a2d88f5d75_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}, {"url": "https://help.prusa3d.com/wp-content/uploads/2025/01/545f445aafe40b64940c685218fb4ace_painted-533x400.jpeg", "original": "https://help.prusa3d.com/wp-content/uploads/2025/01/545f445aafe40b64940c685218fb4ace_painted.jpeg", "credit": ["Prusa Research：公式ガイド写真", "Prusa Research: official guide photo", "Prusa Research: official guide photo", "Prusa Research: official guide photo"]}], "lineIDs": [1040946, 1040947, 1040948, 1040949]}]});
